exports.languageNamesAndCodes = exports.supportedLanguagesTable
  .filter((item) => !item.isDisabled)
  .map((item) => ({
    name: item.name,
    codes: item.supportedCodes.map((code) => code.code),
  }));
/**
 * Specifically for the Dashboard Dropdown where we need to display the language name and a unique code associated with it
 */
const usedCodes = new Set();
exports.languageNamesAndUniqueCodes = exports.supportedLanguagesTable
  .map((item) => {
    if (item.isDisabled) return null;
    const codeToUse = item.supportedCodes.find(
      ({ code }) => !usedCodes.has(code) && !code.includes("_")
    )?.code;
    if (!codeToUse) return null;
    usedCodes.add(codeToUse);
    return { name: item.name, code: codeToUse };
  })
  .filter((item) => item !== null);
